function norm(s){return String(s||'').toLowerCase().replace(/[\u064b-\u065f\u0670]/g,'').replace(/ـ/g,'');}
function classify(p){if(p.kind&&p.kind!=='auto'&&KINDS[p.kind])return{kind:p.kind,explicit:true,alternatives:[],matched:[]};const t=norm(p.name+' '+p.idea);const scored=Object.entries(patterns).map(([k,ps])=>({kind:k,matched:ps.filter(r=>r.test(t)).map(r=>r.source)})).filter(x=>x.matched.length).sort((a,b)=>b.matched.length-a.matched.length);if(!scored.length)return{kind:'general',explicit:false,alternatives:[],matched:[]};return{kind:scored[0].kind,explicit:false,alternatives:scored.slice(1,3).map(x=>x.kind),matched:scored[0].matched};}
